  const expressions = Object.keys(categories).reduce(
    (all, category) => all.concat(categories[category]),
    []
  );
  const existing = Array.isArray(window.KOREAN_EXPRESSIONS) ? window.KOREAN_EXPRESSIONS : [];
  const requiredFields = ["word", "ipa", "meaning", "example", "exampleKo"];
  const categoryCounts = Object.keys(categories).map((category) => categories[category].length);
  const normalized = (value) => value.toLowerCase().normalize("NFC").replace(/[^a-z0-9가-힣]/g, "");
  const words = expressions.map((expression) => normalized(expression.word));
  const examples = expressions.map((expression) => expression.example.trim());
  const existingWords = new Set(existing.map((expression) => normalized(expression.word)));

  if (expressions.length !== 270 || categoryCounts.length !== 10 || categoryCounts.some((count) => count !== 27)) {
    throw new Error(`Expected 270 expressions across 10 equally represented contexts; got ${expressions.length} records.`);
  }
  if (words.some((word, index) => words.indexOf(word) !== index || existingWords.has(word))) {
    throw new Error("Duplicate Korean expression found in the new set or existing list.");
  }
  if (new Set(examples).size !== 270) {
    throw new Error("Every expression must have a distinct contextual example sentence.");
  }
  for (const expression of expressions) {
    if (requiredFields.some((field) => typeof expression[field] !== "string" || !expression[field].trim())) {
      throw new Error("Every Korean expression must include all five required text fields.");
    }
  }

  window.KOREAN_EXPRESSIONS = [...existing, ...expressions];
